    72	    /**
    73	     * 주문 입찰 생성 입력값을 검증합니다.
    74	     */
    75	    private void validateCreateOrderBidInput(String email, Long productSizeId, int bidPrice) {
    76	        if (email == null || email.trim().isEmpty()) {
    77	            throw new OrderBidAccessDeniedException("사용자 이메일이 없습니다.");
    78	        }
    79	        if (productSizeId == null) {
    80	            throw new ProductSizeNotFoundException("상품 사이즈 ID가 없습니다.");
    81	        }
    82	        if (bidPrice <= 0) {
    83	            throw new InvalidBidPriceException("입찰 가격은 0보다 커야 합니다. 현재 가격: " + bidPrice);
    84	        }
    85	    }
    86	
    87	    /**
    88	     * OrderBid 생성 및 저장을 수행합니다.
    89	     */
    90	    private OrderBid createAndSaveOrderBid(User user, ProductSize productSize, int bidPrice, Order order) {
    91	        OrderBid orderBid = OrderBid.builder()
    92	                .user(user)
    93	                .productSize(productSize)
    94	                .bidPrice(bidPrice)
    95	                .status(BidStatus.PENDING)
    96	                .order(order)
    97	                .build();
    98	
    99	        // 양방향 관계 설정
   100	        orderBid.assignOrder(order);
   101	
   102	        return orderBidRepository.save(orderBid);
   103	    }
