  2	
  3	import com.fream.back.domain.order.dto.PayAndShipmentRequestDto;
  4	import com.fream.back.domain.order.dto.kafka.OrderProcessingEvent;
  5	import com.fream.back.domain.order.entity.Order;
  6	import com.fream.back.domain.order.entity.OrderStatus;
  7	import com.fream.back.domain.order.repository.OrderRepository;
  8	import com.fream.back.domain.order.service.command.OrderCommandService;
  9	import com.fream.back.domain.payment.entity.Payment;
 10	import com.fream.back.domain.payment.service.command.PaymentCommandService;
 11	import com.fream.back.domain.shipment.entity.OrderShipment;
 12	import com.fream.back.domain.shipment.service.command.OrderShipmentCommandService;
 13	import com.fream.back.domain.user.entity.User;
 14	import com.fream.back.domain.user.service.query.UserQueryService;
 15	import com.fream.back.domain.warehouseStorage.entity.WarehouseStorage;
 16	import com.fream.back.domain.warehouseStorage.service.command.WarehouseStorageCommandService;
 17	import lombok.RequiredArgsConstructor;
 18	import lombok.extern.slf4j.Slf4j;
 19	import org.springframework.kafka.annotation.KafkaListener;
 20	import org.springframework.kafka.core.KafkaTemplate;
 21	import org.springframework.kafka.support.Acknowledgment;
 22	import org.springframework.messaging.handler.annotation.Payload;
 23	import org.springframework.messaging.simp.SimpMessagingTemplate;
 24	import org.springframework.stereotype.Service;
 25	import org.springframework.transaction.annotation.Transactional;
 26	
 27	import java.time.Duration;
 28	import java.time.Instant;
 29	import java.time.LocalDateTime;
 30	import java.util.HashMap;
 31	import java.util.Map;
 32	
 33	/**
 34	 * 주문 처리 이벤트 컨슈머
 35	 * 결제 + 배송 + 창고보관을 포함한 전체 주문 처리를 트랜잭션으로 처리
 36	 */
 37	@Service
 38	@RequiredArgsConstructor
 39	@Slf4j
 40	public class OrderEventConsumer {
 41	
 42	    private final OrderRepository orderRepository;
 43	    private final PaymentCommandService paymentCommandService;
 44	    private final OrderShipmentCommandService orderShipmentCommandService;
 45	    private final WarehouseStorageCommandService warehouseStorageCommandService;
 46	    private final UserQueryService userQueryService;
 47	    private final OrderEventProducer orderEventProducer;
 48	    private final SimpMessagingTemplate messagingTemplate; // WebSocket 메시지 전송
 49	    private final KafkaTemplate<String, Map<String, Object>> notificationKafkaTemplate;
 50	
 51	    /**
 52	     * 주문 처리 이벤트 리스너
 53	     * 전체 주문 처리를 하나의 트랜잭션으로 수행
 54	     */
 55	    @KafkaListener(
 56	            topics = "order-processing-topic",
 57	            groupId = "order-processing-group",
 58	            containerFactory = "orderProcessingKafkaListenerContainerFactory"
 59	    )
 60	    @Transactional
 61	    public void handleOrderProcessingEvent(
 62	            @Payload OrderProcessingEvent event,
 63	            Acknowledgment acknowledgment) {
 64	
 65	        Instant start = Instant.now();
 66	
 67	        try {
 68	            log.info("주문 처리 이벤트 수신: 주문ID={}, 이벤트ID={}",
 69	                    event.getOrderId(), event.getEventId());
 70	
 71	            // 1. 멱등성 검사 - 이미 처리된 주문인지 확인
 72	            if (isOrderAlreadyProcessed(event.getOrderId())) {
 73	                log.warn("이미 처리된 주문 요청 - 중복 처리 방지: 주문ID={}", event.getOrderId());
 74	                acknowledgment.acknowledge();
 75	                return;
 76	            }
 77	
 78	            // 2. 주문 및 사용자 정보 조회
 79	            Order order = orderRepository.findById(event.getOrderId())
 80	                    .orElseThrow(() -> new IllegalArgumentException(
 81	                            "주문을 찾을 수 없습니다. 주문ID: " + event.getOrderId()));
 82	
 83	            User user = userQueryService.findByEmail(event.getUserEmail());
 84	
 85	            // 3. 권한 확인
 86	            if (!order.getUser().getId().equals(user.getId())) {
 87	                log.error("주문과 사용자 정보 불일치: 주문ID={}, 주문사용자ID={}, 요청사용자ID={}",
 88	                        event.getOrderId(), order.getUser().getId(), user.getId());
 89	                throw new IllegalArgumentException("주문과 사용자 정보가 일치하지 않습니다.");
 90	            }
 91	
 92	            // 4. 전체 주문 처리 수행 (하나의 트랜잭션)
 93	            processCompleteOrder(order, user, event.getRequestDto());
 94	
 95	            // 5. 성공 알림 전송
 96	            sendSuccessNotification(event.getOrderId(), event.getUserEmail());
 97	
 98	            // 6. 처리 완료 ACK
 99	            acknowledgment.acknowledge();
100	
101	            // 처리 시간 로깅
102	            Instant end = Instant.now();
