   191	            String url = "https://trace.cjlogistics.com/next/tracking.html?wblNo=" + trackingNumber;
   192	            Document doc = Jsoup.connect(url).get();
   193	            // tbody#statusDetail 의 마지막 tr => 5번째 td
   194	            Elements rows = doc.select("tbody#statusDetail tr");
   195	            if (rows.isEmpty()) {
