  2	
  3	import com.fream.back.global.utils.PlaywrightBrowserManager;
  4	import lombok.RequiredArgsConstructor;
  5	import org.springframework.batch.core.ExitStatus;
  6	import org.springframework.batch.core.StepExecution;
  7	import org.springframework.batch.core.listener.StepExecutionListenerSupport;
  8	
  9	@RequiredArgsConstructor
 10	public class BrowserManageStepListener extends StepExecutionListenerSupport {
 11	
 12	    private final PlaywrightBrowserManager browserManager;
 13	
 14	    @Override
 15	    public void beforeStep(StepExecution stepExecution) {
 16	        // Step 시작할 때 브라우저 실행
 17	        browserManager.openBrowser();
 18	    }
 19	
 20	    @Override
 21	    public ExitStatus afterStep(StepExecution stepExecution) {
 22	        // Step 끝날 때 브라우저 종료
 23	        browserManager.closeBrowser();
 24	        return stepExecution.getExitStatus();
 25	    }
 26	}

